exercises.solution:
function chineseRemainder(remainders, moduli) {
  function extGcd(a, b) {
    if (b === 0) return { gcd: a, x: 1, y: 0 };
    const { gcd, x, y } = extGcd(b, a % b);
    return { gcd, x: y, y: x - Math.floor(a / b) * y };
  }
  function modInverse(a, m) {
    const { gcd, x } = extGcd(a, m);
    if (gcd !== 1) return -1;
    return ((x % m) + m) % m;
  }
  const N = moduli.reduce((a, b) => a * b, 1);
  let x = 0;
  for (let i = 0; i < moduli.length; i++) {
    const ni = N / moduli[i];
    const inv = modInverse(ni, moduli[i]);
    if (inv === -1) return -1;
    x += remainders[i] * ni * inv;
  }
  return ((x % N) + N) % N;
}

